              (is (= 6 (count descriptors) (count removal-rows)))
              (is (= {:normal 4 :not-invoked 2} (frequencies (map :application descriptors))))
              (is (= 5 (count family)))
              (is (= {:normal 4 :not-invoked 1} (frequencies (map :application family))))
              (is (= 3 (count rows)))
