                  calls (:call-type-facts facts)
                  descriptors (mapv :applied-map-get (filter #(= :direct-map-get (:dispatch %)) calls))
                  rows (filterv #(= :sh08-map-get-v1 (:producer-rule %)) (:constraint-ledger facts))
