      (is (str/includes? original subexpression))
      (is (str/includes? positive subexpression)))
    (doseq [[disposition name functions] [["accepted" "local-runtime-string-predicate" 3]
                                         ["accepted" "local-runtime-string-predicate-transfer" 2]
                                         ["rejected" "string-predicate-zero" 1]]]
