                      (is (= 'gravity.text (:semantic-owner descriptor)))
                      (is (= 'string? (:operation descriptor)))
                      (is (= (if (= :normal application) :gravity.type/bool :gravity.type/never) (:return descriptor) (:result-type descriptor)))
                      (is (= {:operation :string-family-classification :operand-evaluation :once :operand-position :non-tail
