(deftest current-gravity-character-predicate-other-producer-id-guard-development-kernel
  (require 'gravity.self-hosting.sh08-function-call-type-test)
  (let [upstream 'gravity.self-hosting.sh08-function-call-type-test
        base ((ns-resolve upstream 'character-predicate-input) [:gravity.type/character])
        second-input (let [renamed (walk/postwalk-replace {:call :second-call :operator :second-operator :arg0 :second-arg} base)
                           ;; The normalized IDs overlap fixed Core vocabulary.
                           ;; Restore semantic tags in every node representation.
                           restore-node (fn [node]
                                          (cond-> node
                                            (= :second-call (:node-id node)) (assoc :core-form :call)
                                            (= :second-operator (:node-id node)) (assoc-in [:attributes :position] :operator)))]
                       (-> renamed (assoc :call (:second-call renamed)) (dissoc :second-call)
                           (update :node restore-node)
                           (update :nodes #(into {} (map (fn [[id node]] [id (restore-node node)]) %)))
                           (update-in [:core :nodes] #(mapv restore-node %))
                           (assoc-in [:edge :ordinal] 1) (assoc-in [:core :call-edges 0 :ordinal] 1)))
        derive (ns-resolve upstream 'character-predicate-derived) c7 (ns-resolve upstream 'invoke-c7)
        first-result (derive base 65536) second-result (derive second-input 65536)
        descriptor (:descriptor first-result) second-descriptor (:descriptor second-result)
        path (bootstrap/p15-s23-stage2-compiler-artifact-source-path)
        emitter (:emitter (bootstrap/c-backend-stage2-plan-emitter-source-rule! path :jvm))
        plan (bootstrap/p15-s23-stage2-compiler-artifact-plan emitter path (slurp path))
        context {:core (assoc (:core base) :nodes (into (get-in base [:core :nodes]) (get-in second-input [:core :nodes]))
                          :calls [(:call base) (:call second-input)] :call-edges [(:edge base) (:edge second-input)])
                 :nodes (merge (:nodes base) (:nodes second-input))
                 :forms (merge (:forms base) (:forms second-input)) :bindings (:bindings base)
                 :types (merge (:types base) (:types second-input)
                           {:operator descriptor :call (:type first-result)
                            :second-operator second-descriptor :second-call (:type second-result)})
                 :calls {:call (:call base) :second-call (:call second-input)}
                 :edges {:call (:edge base) :second-call (:edge second-input)} :call-order {:call 0 :second-call 1}
                 :call-facts {:call (c7 'sh08-chp-call-fact [descriptor (:module base)])
                              :second-call (c7 'sh08-chp-call-fact [second-descriptor (:module base)])}
                 :ledger [(c7 'sh08-chp-constraint [descriptor]) (c7 'sh08-chp-constraint [second-descriptor])]
                 :locals {:arg0 'value} :parameter-types (:types base)}
        compile (fn [ctx budget]
                  (bootstrap/p15-s23-stage2-runtime-execute-function runtime plan 'p15-s23-typed-compile-character-predicate
                    [ctx (get-in base [:nodes :call]) budget]))
        callbacks (atom 0)
        hostile (proxy [Object] []
                  (equals [_] (swap! callbacks inc) (throw (AssertionError. "Character ledger compared opaque operator")))
                  (hashCode [] (swap! callbacks inc) (throw (AssertionError. "Character ledger hashed opaque operator"))))
        forged (assoc-in context [:calls :second-call :operator-node-id] hostile)]
    (is (= :accepted (:status first-result) (:status second-result)))
    (is (= :complete (:status (compile context 65536))))
    (doseq [budget [0 65536]]
      (is (= :rejected (:status (compile forged budget)))))
    (is (zero? @callbacks))))

(deftest current-gravity-nil-predicate-lowering-runtime-development-kernel
  (require 'gravity.self-hosting.sh08-function-call-type-test)
  (let [upstream 'gravity.self-hosting.sh08-function-call-type-test
        input-fn (ns-resolve upstream 'nil-predicate-input)
        derive (ns-resolve upstream 'nil-predicate-derived)
        c7 (ns-resolve upstream 'invoke-c7)
        path (bootstrap/p15-s23-stage2-compiler-artifact-source-path)
        emitter (:emitter (bootstrap/c-backend-stage2-plan-emitter-source-rule! path :jvm))
        emitter-plan (bootstrap/p15-s23-stage2-compiler-artifact-plan emitter path (slurp path))
        lower (fn [name & args] (bootstrap/p15-s23-stage2-runtime-execute-function runtime emitter-plan name (vec args)))]
    (let [body (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'leaf)
          ip-input (ns-resolve upstream 'integer-predicate-input)]
      (doseq [target [:jvm :wasm]
              [input name expected] [[(input-fn [:gravity.type/map]) 'nilp (= target :jvm)]
                                     [(ip-input [:gravity.type/integer]) 'ip true]]]
        (let [binding (get-in input [:bindings :ordering-binding]) module (assoc (:module input) :target target)]
          (is (= expected (c7 (symbol (str "sh08-" name "-binding?")) [binding module])))
          (is (= expected (body (symbol (str "body-" name "-binding?")) binding module)))
          (is (= expected (lower (symbol (str "p15-s23-" name "-binding?")) binding module))))))
    (doseq [type [:gravity.type/nil :gravity.type/integer
                  {:kind :gravity.type/nil-or :value-type :gravity.type/bool}
                  {:kind :gravity.type/nil-or :value-type :gravity.type/character}
                  {:kind :gravity.type/nil-or :value-type :gravity.type/string}
                  {:kind :gravity.type/nil-or :value-type :gravity.type/symbol}
                  {:kind :gravity.type/nil-or :value-type :gravity.type/keyword}
                  :gravity.type/bool :gravity.type/set :gravity.type/map :gravity.type/keyword :gravity.type/never
                  {:kind :gravity.type/set :shape :literal :element-types [:gravity.type/keyword :gravity.type/string]}
                  {:kind :gravity.type/map :shape :literal :member-types [:gravity.type/keyword :gravity.type/bool]}
                  {:kind :gravity.type/vector :shape :literal :element-types [:gravity.type/keyword]}]]
      (let [{:keys [core nodes forms bindings types module call edge] :as input} (input-fn [type])
            result (derive input 65536) descriptor (:descriptor result)
            context {:core core :nodes nodes :forms forms :bindings bindings
                     :types (assoc types :operator descriptor :call (:type result))
                     :calls {:call call} :edges {:call edge} :call-order {:call 0}
                     :call-facts {:call (c7 'sh08-nilp-call-fact [descriptor module])}
                     :ledger [(c7 'sh08-nilp-constraint [descriptor])] :locals {:arg0 'value} :parameter-types types}
            compile #(lower 'p15-s23-typed-compile-node % :call %2)
            compiled (compile context 65536)]
        (is (= :complete (:status compiled)) (pr-str (select-keys compiled [:status :facts :work-count])))
        (when-not (= :complete (:status compiled))
          (throw (ex-info "Nil predicate lowering prerequisite rejected" (select-keys compiled [:status :facts :work-count]))))
