    (let [c17-path (.getPath (io/file root "bootstrap/gravity/src/gravity/compiler/w5_c17_plugin_executor.gravity"))
          c17-forms (bootstrap/read-forms c17-path (slurp c17-path))
          owner (first (filter #(and (seq? %) (= 'defn (first %)) (= 'w5-c17-validate-capabilities (second %))) c17-forms))
          comparison (first (filter #(and (seq? %) (= '= (first %)) (= 'declared (second %))) (tree-seq coll? seq owner)))
          relative "bootstrap/clojure/fixtures/self-hosting/sh-08/accepted/local-runtime-keyword-set-inequality.gravity"
          positive-path (.getPath (io/file root relative))
          positive (bootstrap/read-forms positive-path (slurp positive-path))
          producer (first (filter #(and (seq? %) (= 'defn (first %)) (= 'declared (second %))) positive))]
