        (is (= :rejected (:status (c7 'sh08-ane-inferred-call [core node call edge nodes bindings (merge typed types) 65536]))))
        (let [validation (c7 'sh08-ane-type-work [[(:arg0 types) (:arg1 types)] 65536])]
