                    (is (= 3 (count ordinary)))
                    (doseq [call ordinary] (is (= #{:op :function :args} (set (keys call)))))
                    (is (= range (get-in helper [:type-input :indexed-private-self :source-induction])))
                    (is (= #{(:call-core-node-id addition) (:call-core-node-id access)}
                           (set (keys (get-in helper [:type-input :indexed-private-self :operations])))))
                    (doseq [[name function] (:functions assembled)]
                      (is (= path (get-in function [:typed-lowering-provenance :source :path])) (str extension " " name))
                      (is (= (= name 'w5-se-member-from?) (contains? (:type-input function) :indexed-private-self))))
                    (doseq [descriptor [addition access]]
                      (let [id (:call-core-node-id descriptor) instruction (first (filter #(= id (get-in % [:proof :operation-core-node-id])) instructions))]
                        (is (= (:operation descriptor) (:function instruction)))
                        (is (= 2 (count (:args instruction))))
                        (is (= [:local (if (= '+ (:operation descriptor)) :literal :local)] (mapv :op (:args instruction))))
                        (is (= #{} (get-in graph [:nodes id :direct])))
                        (is (= (get-in descriptor [:source-call :ordered-evaluation-node-ids]) (get-in graph [:nodes id :dependencies])))))
                    (is (= [] (get-in graph [:functions (:function-syntax-id proof) :throws])))
                    {:input input :assembled assembled :module module :definitions definitions :proof proof :range range
                     :addition addition :access access :binding binding :effects effects :graph graph :results results}))
                [".gravity" ".qst"])
        {:keys [input module definitions addition binding effects graph]} (first cases)
        hostile (assoc-in (:typed input) [:identity-input :recursive-proof :parameter-value-premise :source-induction :unit-source :value] 2)
        failure (operation #(diagnostic (fn [] (bootstrap/p15-s23-stage2-compile-function
                                                 emitter module (get definitions 'w5-se-member-from?) (assoc input :typed hostile)))))]
    (is (= (get-in cases [0 :input :typed :identity-input]) (get-in cases [1 :input :typed :identity-input])))
    (is (= (:graph (first cases)) (:graph (second cases))))
    (is (= (:results (first cases)) (:results (second cases))))
    (is (= (typed-functions-without-source-path (get-in cases [0 :assembled :functions]))
           (typed-functions-without-source-path (get-in cases [1 :assembled :functions]))))
    (is (= "P15S23Q002" (:id failure)))
    (is (= :rejected (:status (last @verified))))
    (is (= 3 (count @verified)))
    (is (= :rejected (:status (c8 'verify-body-effect-result (:typed input) (:verification input) binding
                              (reseal effects (update-in graph [:nodes (:call-core-node-id addition) :dependencies] pop))))))
    (doseq [suffix ["entry" "step" "needle" "vector" "public" "unseeded"]]
      (let [relative (str "bootstrap/clojure/fixtures/self-hosting/sh-08/rejected/indexed-private-self-" suffix ".gravity")
            products (fresh relative) diagnostics (get-in products [:typed :diagnostics])]
        (is (= :accepted (get-in products [:c5 :status])) suffix)
        (is (= :passed (get-in products [:report :status])) suffix)
        (is (= :rejected (get-in products [:typed :status])) suffix)
        (is (vector? diagnostics) suffix)
        (is (seq diagnostics) suffix)
        (is (every? #(and (string? (:rule %)) (keyword? (:reason %))) diagnostics) (pr-str [suffix diagnostics]))
        (is (= (get indexed-private-source-negative-reasons suffix)
               (mapv (juxt :rule :reason) diagnostics)) (pr-str [suffix diagnostics]))
        (println (pr-str {:aw-indexed-source-negative suffix :diagnostics diagnostics}))))))

(deftest current-gravity-bounded-unit-addition-authenticated-composition
  ;; Sole affected source composition; six existing runtime-projection loader assertions.
  (require 'gravity.self-hosting.sh08-function-call-type-test)
  (let [root (loop [directory (.getParentFile (io/file (module-fixture "seed-library" ".gravity")))]
               (if (.isFile (io/file directory "deps.edn")) directory (recur (.getParentFile directory))))
        fresh (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'fresh-type-products)
        seal (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'seal-binding)
        reseal (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'reseal-effect-graph)
        c8 (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'leaf)
        runtime-plan (:plan (typed-catch-runtime-projection))
        emitter-path (bootstrap/p15-s23-stage2-compiler-artifact-source-path)
        emitter (:emitter (bootstrap/c-backend-stage2-plan-emitter-source-rule! emitter-path :jvm))
        original bootstrap/p15-s23-stage2-runtime-execute-function verified (atom [])
        operation (fn [thunk]
                    (let [before (count @verified)
                          result (with-redefs [bootstrap/p15-s23-stage2-runtime-execute-function
                                               (fn [runtime plan function args]
                                                 (let [result (original runtime plan function args)]
                                                   (when (= function 'sh08-verify-function-type-result) (swap! verified conj result)) result))]
                                   (thunk))]
                      (is (= 1 (- (count @verified) before))) result))
        cases
        (mapv
          (fn [extension]
            (let [relative (str "bootstrap/clojure/fixtures/self-hosting/sh-08/accepted/local-runtime-bounded-unit-addition" extension)
                  path (.getPath (io/file root relative)) products (fresh relative)
                  input (select-keys products [:request :typed :verification])
                  ready (is (= :accepted (get-in input [:typed :status])) (pr-str (get-in input [:typed :diagnostics])))
                  _ (when-not ready (throw (ex-info "Unit addition C7 source rejected" {:diagnostics (get-in input [:typed :diagnostics])})))
                  _ (is (= :passed (get-in input [:verification :status])))
                  _ (when-not (= :passed (get-in input [:verification :status]))
                      (throw (ex-info "Unit addition C7 verification failed" {:verification (:verification input)})))
                  artifact (get-in input [:request :b47-context :authenticated-wrapper :sh06-resolution-artifact :sh05-macro-artifact])
                  parsed (get-in artifact [:gravity-macro-boundary :authenticated-sh04-artifact :c2-reader-artifact :parsed-semantic-values])
                  raw-module (assoc (bootstrap/parse-module path parsed) :forms (:expanded-forms artifact))
                  definitions (bootstrap/stage0-function-table raw-module) module (assoc raw-module :function-table definitions)
                  assembled (operation #(bootstrap/p15-s23-stage2-assemble-plan-products emitter module (vec (sort-by key definitions)) input))
                  core (get-in input [:request :canonical-core-artifact]) facts (get-in input [:typed :identity-input])
                  nodes (into {} (map (juxt :node-id identity) (:nodes core)))
                  forms (into {} (map (juxt :form-id identity) (get-in input [:request :b47-context :authenticated-core-request :forms])))
                  functions (into {} (map (juxt :definition-name identity) (:function-type-table facts)))
                  calls (:call-type-facts facts)
                  additions (mapv :applied-bounded-unit-addition (filter #(= :direct-bounded-unit-addition (:dispatch %)) calls))
                  successors (mapv :applied-bounded-successor (filter #(= :direct-bounded-successor (:dispatch %)) calls))
                  forward (first (filter #(= (get-in functions ['forward :function-id]) (get-in % [:source-edge :caller-function-syntax-id])) additions))
                  mixed (first (filter #(= (get-in functions ['mixed :function-id]) (get-in % [:source-edge :caller-function-syntax-id])) additions))
                  access (:applied-vector-get (first (filter #(= :direct-vector-get (:dispatch %)) calls)))
                  steps (vec (concat additions successors))
                  instructions (filter #(and (map? %) (= :builtin-call (:op %))) (tree-seq coll? seq (:functions assembled)))
                  binding (seal (:request input) (:typed input) (:verification input))
                  effects (c8 'build-body-effect-result (:typed input) (:verification input) binding)
                  _ (is (= :accepted (:status effects)) (pr-str (:diagnostics effects)))
                  _ (when-not (= :accepted (:status effects))
                      (throw (ex-info "Unit addition C8 effects rejected before execution" {:diagnostics (:diagnostics effects)})))
                  effect-verification (c8 'verify-body-effect-result (:typed input) (:verification input) binding effects)
                  _ (is (= :passed (:status effect-verification)))
                  _ (when-not (= :passed (:status effect-verification))
                      (throw (ex-info "Unit addition C8 verification failed before execution" {:verification effect-verification})))
                  graph (:effect-graph effects)
                  results (mapv (fn [[name args expected tag]]
                                  (let [result (original runtime runtime-plan 'p15-s23-runtime-evaluate-in-context
                                                         [{:op :function-call :function name :args (literal-instructions args)}
                                                          {} "" (:functions assembled) []])]
                                    (is (= [expected "" tag] result) (str extension " " name " " args))
                                    result))
                                [['forward [:keep] 3 :normal]
                                 ['mixed [true :keep] 3 :normal] ['mixed [false :keep] 3 :normal]
                                 ['mixed [true :stop] :stop :thrown] ['mixed [false :stop] :stop :thrown]
                                 ['caught [true] true :normal] ['caught [false] true :normal] ['main [] 3 :normal]])]
              (is (= 4 (count (:function-records core)) (count (:function-type-table facts)) (count (:functions assembled))))
              (is (= 13 (count (:calls core)) (count (:call-edges core)) (count calls)))
              (is (= 2 (count (:loop-bindings core)) (count additions)))
              (is (= 3 (count (:recur-transfers core)) (count steps)))
              (is (= 1 (count successors)))
              (is (= {:sh08-bounded-unit-addition-v1 2 :sh08-bounded-successor-v2 1} (frequencies (map :version steps))))
              (is (= 2 (count (filter #(= :sh08-bounded-unit-addition-v1 (:producer-rule %)) (:constraint-ledger facts)))))
              (is (= 1 (count (filter #(= :sh08-bounded-successor-v2 (:producer-rule %)) (:constraint-ledger facts)))))
              (is (empty? (filter #(= :sh08-bounded-successor-v1 (:producer-rule %)) (:constraint-ledger facts))))
              (is (= ['+] (mapv :operation (get-in forward [:range-proof :step-sources]))))
              (is (= ['+ 'inc] (mapv :operation (get-in mixed [:range-proof :step-sources]))))
              (doseq [descriptor steps]
                (let [proof (:range-proof descriptor) addition? (= '+ (:operation descriptor))
                      record (get-in graph [:nodes (:call-core-node-id descriptor)])]
                  (is (= ['gravity.math 'gravity.math.core :proof-required] ((juxt :semantic-owner :layer0-owner :numeric-mode) descriptor)))
                  (is (= (if addition? [:gravity.type/integer :gravity.type/integer] [:gravity.type/integer]) (:argument-types descriptor)))
                  (is (= :sh08-bounded-unit-step-v2 (:version proof)))
                  (is (= [:proven-safe :retained :not-authorized] ((juxt :outcome :runtime-guards :check-elision) proof)))
                  (is (= (count (:incoming-transfers proof)) (count (:backedge-paths proof)) (count (:step-sources proof))))
                  (is (= #{} (:direct record)))
                  (is (nil? (:allocation record)))
                  (is (= (get-in descriptor [:source-call :ordered-evaluation-node-ids]) (:dependencies record)))
                  (doseq [step (:step-sources proof) :when (= '+ (:operation step))]
                    (let [unit (:unit-node step)]
                      (is (= unit (nodes (:node-id unit))))
                      (is (= :literal (:core-form unit)))
                      (is (= :integer (get-in unit [:attributes :literal-kind]) (get-in step [:unit-source :kind])))
                      (is (= 1 (get-in unit [:attributes :value]) (get-in step [:unit-source :value])))
                      (is (= (:unit-source step) (forms (get-in unit [:source :form-id]))))))))
              (is (= :sh08-vector-get-loop-v1 (:version access)))
              (is (contains? (set (concat (remove #{forward} additions) successors)) (get-in access [:bounds-proof :loop-invariant])))
              (is (= 10 (count instructions)))
              (is (= {'+ 2 'inc 1 'count 2 '< 2 'nth 1 '= 2} (frequencies (map :function instructions))))
              (doseq [descriptor additions]
                (let [instruction (first (filter #(= (:call-core-node-id descriptor) (get-in % [:proof :operation-core-node-id])) instructions))]
                  (is (= '+ (:function instruction)))
                  (is (= [:local :literal] (mapv :op (:args instruction))))
                  (is (= 1 (get-in instruction [:args 1 :value])))
                  (is (= :gravity.runtime/bounded-unit-addition (get-in instruction [:proof :kind])))
                  (is (= (get-in descriptor [:source-call :argument-node-ids 1]) (get-in instruction [:proof :unit-core-node-id])))))
              (doseq [[name function] (:functions assembled)]
                (is (= path (get-in function [:typed-lowering-provenance :source :path])) (str extension " " name)))
              (is (= [] (get-in graph [:functions (get-in functions ['forward :function-id]) :throws])))
              (is (= [:gravity.type/keyword] (get-in graph [:functions (get-in functions ['mixed :function-id]) :throws])))
              (is (= [] (get-in graph [:functions (get-in functions ['caught :function-id]) :throws])))
              (when (= extension ".gravity")
                (let [analyze #(c8 'body-analyze-module (:request input) facts {} %)
                      analyzed (analyze 65536) work (:work-count analyzed)]
                  (is (= :accepted (:status analyzed)) (pr-str analyzed))
                  (is (= graph (:graph analyzed)))
                  (is (= analyzed (analyze work)))
                  (is (= :rejected (:status (analyze (dec work)))))))
              {:input input :module module :definitions definitions :assembled assembled :descriptor mixed
               :binding binding :effects effects :graph graph :results results}))
          [".gravity" ".qst"])
        {:keys [input module definitions descriptor binding effects graph]} (first cases)
        forged (assoc-in descriptor [:range-proof :step-sources 0 :unit-source :value] 2)
        hostile (walk/prewalk #(if (= % descriptor) forged %) (:typed input))
        failure (operation #(diagnostic (fn [] (bootstrap/p15-s23-stage2-compile-function
                                                 emitter module (get definitions 'mixed) (assoc input :typed hostile)))))]
    (is (= (get-in cases [0 :input :typed :identity-input]) (get-in cases [1 :input :typed :identity-input])))
    (is (= (:graph (first cases)) (:graph (second cases))))
    (is (= (:results (first cases)) (:results (second cases))))
    (is (= (typed-functions-without-source-path (get-in cases [0 :assembled :functions]))
       (typed-functions-without-source-path (get-in cases [1 :assembled :functions]))))
    (is (= "P15S23Q002" (:id failure)))
    (is (= :rejected (:status (last @verified))))
    (is (= 3 (count @verified)))
    (let [id (:call-core-node-id descriptor) changed (update-in graph [:nodes id :dependencies] pop)]
      (is (= :rejected (:status (c8 'verify-body-effect-result (:typed input) (:verification input) binding (reseal effects changed))))))
    (doseq [[suffix expected] [["unit" #{["C7-VERIFY" :bounded-successor-integer-source-required]}]
                               ["nonstrict" #{["STD5001" :bounded-successor-range-proof-required]}]
                               ["mixed" #{["C7-VERIFY" :bounded-successor-integer-source-required]
                                           ["STD5001" :bounded-successor-range-proof-required]}]]]
      (let [products (fresh (str "bootstrap/clojure/fixtures/self-hosting/sh-08/rejected/bounded-unit-addition-" suffix ".gravity"))
            diagnostics (get-in products [:typed :diagnostics])]
        (is (= :rejected (get-in products [:typed :status])) suffix)
        (is (some expected (map (juxt :rule :reason) diagnostics)) (pr-str [suffix diagnostics]))))))

(deftest current-gravity-bounded-successor-authenticated-composition
  (require 'gravity.self-hosting.sh08-function-call-type-test)
  (let [root (loop [directory (.getParentFile (io/file (module-fixture "seed-library" ".gravity")))]
               (if (.isFile (io/file directory "deps.edn")) directory (recur (.getParentFile directory))))
        fresh (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'fresh-type-products)
        seal (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'seal-binding)
        reseal (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'reseal-effect-graph)
        c8 (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'leaf)
        c7 (ns-resolve 'gravity.self-hosting.sh08-function-call-type-test 'invoke-c7)
        runtime-plan (:plan (typed-catch-runtime-projection))
        emitter-path (bootstrap/p15-s23-stage2-compiler-artifact-source-path)
        emitter (:emitter (bootstrap/c-backend-stage2-plan-emitter-source-rule! emitter-path :jvm))
        original bootstrap/p15-s23-stage2-runtime-execute-function verified (atom [])
        operation (fn [thunk]
                    (let [before (count @verified)
                          result (with-redefs [bootstrap/p15-s23-stage2-runtime-execute-function
                                               (fn [runtime plan function args]
                                                 (let [result (original runtime plan function args)]
                                                   (when (= function 'sh08-verify-function-type-result) (swap! verified conj result)) result))]
                                   (thunk))]
                      (is (= 1 (- (count @verified) before))) result))
        specs [['empty-counter [] 0] ['one-counter [false] 1] ['one-counter [true] 1]
               ['multiple-counter [true] 3] ['multiple-counter [false] 3] ['main [] 3]]
        cases (mapv
                (fn [extension]
                  (let [relative (str "bootstrap/clojure/fixtures/self-hosting/sh-08/accepted/local-runtime-bounded-successor" extension)
                        path (.getPath (io/file root relative)) products (fresh relative)
                        input (select-keys products [:request :typed :verification])
                        ready (is (= :accepted (get-in input [:typed :status])) (pr-str (take 3 (get-in input [:typed :diagnostics]))))
                        _ (when-not ready (throw (ex-info "Successor source rejected before lowering" {:diagnostics (get-in input [:typed :diagnostics])})))
                        artifact (get-in input [:request :b47-context :authenticated-wrapper :sh06-resolution-artifact :sh05-macro-artifact])
                        parsed (get-in artifact [:gravity-macro-boundary :authenticated-sh04-artifact :c2-reader-artifact :parsed-semantic-values])
                        raw-module (assoc (bootstrap/parse-module path parsed) :forms (:expanded-forms artifact))
                        definitions (bootstrap/stage0-function-table raw-module) module (assoc raw-module :function-table definitions)
                        standalone (operation #(bootstrap/p15-s23-stage2-compile-function emitter module (get definitions 'multiple-counter) input))
                        assembled (operation #(bootstrap/p15-s23-stage2-assemble-plan-products emitter module (vec (sort-by key definitions)) input))
                        core (get-in input [:request :canonical-core-artifact]) facts (get-in input [:typed :identity-input])
                        calls (:call-type-facts facts) successors (filterv #(= :direct-bounded-successor (:dispatch %)) calls)
                        descriptors (mapv :applied-bounded-successor successors)
                        function-index (into {} (map (juxt :definition-name identity) (:function-type-table facts)))
                        by-name (fn [name] (filterv #(= (get-in function-index [name :function-id])
                                                        (get-in % [:source-edge :caller-function-syntax-id])) descriptors))
                        instructions (atom [])
                        _ (walk/postwalk #(do (when (and (map? %) (= :builtin-call (:op %))) (swap! instructions conj %)) %) (:functions assembled))
                        binding (seal (:request input) (:typed input) (:verification input))
                        effects (c8 'build-body-effect-result (:typed input) (:verification input) binding)
                        graph (:effect-graph effects)]
                    (is (= :passed (get-in input [:verification :status])))
                    (is (= 4 (count (:function-records core)) (count (:function-type-table facts)) (count (:functions assembled))))
                    (is (= 11 (count (:calls core)) (count (:call-edges core)) (count calls)))
                    (is (= 3 (count (:loop-bindings core))))
                    (is (= 7 (count (:recur-targets core))))
                    (is (= 4 (count (:recur-transfers core)) (count successors) (count (filter #(= :sh08-bounded-successor-v1 (:producer-rule %)) (:constraint-ledger facts)))))
                    (is (= {:direct-bounded-successor 4 :direct-collection-count 3 :direct-integral-ordering 3 nil 1} (frequencies (map :dispatch calls))))
                    (let [local-edges (filterv #(= :local-function (:classification %)) (:call-edges core))
                          local-facts (filterv #(nil? (:dispatch %)) calls)
                          edge (first local-edges) fact (first local-facts)]
                      (is (= 1 (count local-edges) (count local-facts)))
                      (is (= [(:call-core-node-id edge) (get-in function-index ['main :function-id])
                              (get-in function-index ['multiple-counter :function-id])]
                             [(:call-core-node-id edge) (:caller-function-syntax-id edge) (:callee-function-syntax-id edge)]
                             [(:call-core-node-id fact) (:caller-function-syntax-id fact) (:callee-function-syntax-id fact)])))
                    (is (= standalone (get-in assembled [:functions 'multiple-counter])))
                    (is (= 10 (get-in assembled [:instruction-summary :builtin-call]) (count @instructions)))
                    (is (= {'inc 4 'count 3 '< 3} (frequencies (map :function @instructions))))
                    (is (= {0 1 1 1 3 2} (frequencies (map #(get-in % [:proof :vector-extent]) (filter #(= 'inc (:function %)) @instructions)))))
                    (doseq [[_ function] function-index]
                      (is (= :gravity.type/integer (:return function))))
                    (doseq [descriptor descriptors]
                      (let [proof (:range-proof descriptor)]
                        (is (= :gravity.type/integer (:return descriptor) (:result-type descriptor)))
                        (is (= [:gravity.type/integer] (:argument-types descriptor) (:parameter-types descriptor)))
                        (is (= :normal (:application descriptor)))
                        (is (= 'gravity.math (:semantic-owner descriptor)))
                        (is (= 'gravity.math.core (:layer0-owner descriptor)))
                        (is (= :proof-required (:numeric-mode descriptor) (:numeric-mode proof)))
                        (is (= :proven-safe (:outcome proof)))
                        (is (= :retained (:runtime-guards proof)))
                        (is (= :not-authorized (:check-elision proof)))
                        (is (= :not-claimed (:termination proof)))
                        (is (= [] (:direct-effects descriptor) (:latent-effects descriptor) (:thrown-error-effects descriptor)))
                        (is (= 7 (count (:source-call descriptor))))
                        (is (= 12 (count (:source-edge descriptor))))
                        (is (nil? (get-in descriptor [:source-edge :callee-function-syntax-id])))
                        (is (= 1024 (:maximum-vector-extent proof)))
                        (is (= (:vector-extent proof) (get-in proof [:invariant :upper])))
                      ))
                    (is (false? (get-in (first (by-name 'empty-counter)) [:range-proof :guarded-edge :satisfiable])))
                    (is (= 2 (count (get-in (first (by-name 'one-counter)) [:range-proof :vector-origin :binding-links]))))
                    (doseq [descriptor (by-name 'multiple-counter)]
                      (is (= 2 (count (get-in descriptor [:range-proof :incoming-transfers]))
                               (count (get-in descriptor [:range-proof :backedge-paths])))))
                    (doseq [[name args expected] specs]
                      (is (= [expected "" :normal]
                             (original runtime runtime-plan 'p15-s23-runtime-evaluate-in-context
                                       [{:op :function-call :function name :args (literal-instructions args)} {} "" (:functions assembled) []]))
                          (str extension " " name)))
                    (is (= :accepted (:status effects)) (pr-str (:diagnostics effects)))
                    (is (= :passed (:status (c8 'verify-body-effect-result (:typed input) (:verification input) binding effects))))
                    (doseq [descriptor descriptors]
                      (let [record (get-in graph [:nodes (:call-core-node-id descriptor)])]
                        (is (= #{} (:direct record)))
                        (is (nil? (:allocation record)))
                        (is (nil? (:call-body-dependency record)))
                        (is (= (get-in descriptor [:source-call :ordered-evaluation-node-ids]) (:dependencies record)))))
                    (doseq [[_ function] function-index]
                      (is (= #{:memory/allocate} (get-in graph [:functions (:function-id function) :inferred]))))
                    {:input input :module module :definitions definitions :descriptors descriptors :binding binding :effects effects :function-index function-index}))
                [".gravity" ".qst"])
        {:keys [input module definitions descriptors binding effects function-index]} (first cases)
        descriptor (first (filter #(= (get-in function-index ['one-counter :function-id])
                                       (get-in % [:source-edge :caller-function-syntax-id])) descriptors))
        stale (assoc-in descriptor [:range-proof :vector-origin :source-form :value] :altered-source-echo)]
    (is (= (get-in cases [0 :input :typed :identity-input]) (get-in cases [1 :input :typed :identity-input])))
    (is (not= descriptor stale))
    (let [core (get-in input [:request :canonical-core-artifact]) nodes (into {} (map (juxt :node-id identity) (:nodes core)))
          bindings (into {} (map (juxt :binding-id identity) (get-in input [:request :b47-context :authenticated-core-request :binding-table])))]
      ;; Finite range checking does not parse an unused source-value echo;
      ;; the public producer verifier authenticates the complete source echo.
      (is (true? (c7 'sh08-si-inferred-call-valid?
                     [core (nodes (:call-core-node-id descriptor)) (:source-call descriptor) (:source-edge descriptor) nodes bindings
                      (assoc (get-in input [:typed :identity-input :type-table]) (:operator-node-id descriptor) stale)]))))
    (doseq [replacement [(-> descriptor (assoc-in [:range-proof :vector-extent] 2) (assoc-in [:range-proof :invariant :upper] 2))
                         (assoc-in descriptor [:range-proof :count-query :source-call :argument-node-ids]
                                   [(get-in descriptor [:range-proof :vector-origin :node :node-id])])
                         stale]]
      (let [typed (walk/prewalk #(if (= % descriptor) replacement %) (:typed input))
            failure (operation #(diagnostic (fn [] (bootstrap/p15-s23-stage2-compile-function emitter module (get definitions 'multiple-counter)
                                                                                                (assoc input :typed typed)))))]
        (is (= "P15S23Q002" (:id failure)))
        (is (= :rejected (:status (last @verified))))))
    (is (= 7 (count @verified)))
    (let [graph (:effect-graph effects) id (:call-core-node-id descriptor)
