(defn- private-entry-vector-get-selection-matches? [entry]
  (let [parts (filterv #(= :signatures (:key %)) (get-in entry [:argument-shape :parts]))]
    (and (= 1 (count parts))
         (= (first parts) (:selected-part entry))
         (= (:coordinate (first parts)) (:selected-coordinate entry)))))

