        t3 (System/nanoTime)
        runtime-plan (:plan (typed-catch-runtime-projection))
        result (original runtime runtime-plan 'p15-s23-runtime-evaluate-in-context
                         [{:op :function-call :function 'main :args []} {} "" (:functions assembled) []])
