      (is (= :accepted (get-in negative [:c5 :status])))
      (is (= :passed (get-in negative [:report :status])))
      (is (= :rejected (get-in negative [:typed :status])))
      (is (some #(= ["C7-ANNOTATION" :map-get-private-first-entry-presence-required]
