      (is (= :passed (get-in negative [:report :status])))
      (is (= :rejected (get-in negative [:typed :status])))
      (is (some #(= ["C7-TYPE-MISMATCH" :vector-equality-operand-type-required] ((juxt :rule :reason) %)) diagnostics)
