    (let [say (fn [label expr] {:op :do :body [{:op :println :args [(literal label)] :effect :io/write :capability :io/stdout} expr]})
          payload (String. "original Symbol insertion transfer")]
      (is (= [#{'a 'b} "items\nvalue\n" :normal]
